import java.util.*;

class Solution {
    public int[] minInterval(int[][] intervals, int[] queries) {
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
        Integer[] order = new Integer[queries.length];
        for (int i = 0; i < queries.length; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(queries[a], queries[b]));
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0])); // {size, end}
        int[] res = new int[queries.length];
        int idx = 0;
        for (int qIdx : order) {
            int q = queries[qIdx];
            while (idx < intervals.length && intervals[idx][0] <= q) {
                pq.offer(new int[]{intervals[idx][1] - intervals[idx][0] + 1, intervals[idx][1]});
                idx++;
            }
            while (!pq.isEmpty() && pq.peek()[1] < q) pq.poll();
            res[qIdx] = pq.isEmpty() ? -1 : pq.peek()[0];
        }
        return res;
    }
}
